def grouped() -> list[tuple[str, str, list[dict]]]:
    """給樣板畫 `<optgroup>`：[(模式, 分組名稱, 那一組的範例), …]。"""
    return [(m, name, [e for e in EXAMPLES if e["mode"] == m and e["issuer"] == iss])
            for iss, m, name in GROUPS]
